S = input()
char_count = {}
for s in S:
    if s in char_count:
        char_count[s] += 1
    else:
        char_count[s] = 1

frequency_count = {}
for count in char_count.values():
    if count in frequency_count:
        frequency_count[count] += 1
    else:
        frequency_count[count] = 1

ans = "Yes"
